WITH session_summary AS (SELECT session_id, AVG(duration_sec) AS avg_duration_sec, MIN(event_time) AS first_event_time FROM web_events WHERE duration_sec BETWEEN 168 AND 337 GROUP BY session_id) SELECT s.id, s.browser, s.started_at, ss.avg_duration_sec, ss.first_event_time FROM sessions s INNER JOIN session_summary ss ON s.id = ss.session_id WHERE ss.avg_duration_sec >= 420 ORDER BY s.browser DESC;
